let _markdown = "\n\nOverview [#overview]\n\n<FeedbackBlock id=\"6bfc7c2a8e402a84\" body=\"Fumadocs UI maintains support for both Base UI and Radix UI, while it uses Radix UI by default.\">\n  Fumadocs UI maintains support for both **Base UI** and **Radix UI**, while it uses Radix UI by default.\n</FeedbackBlock>\n\n<FeedbackBlock id=\"174cda43954ecc37\" body=\"The configuration may be different if you use Fumadocs CLI for customising components.\">\n  The configuration may be different if you use Fumadocs CLI for customising components.\n</FeedbackBlock>\n\nBase UI [#base-ui]\n\n<FeedbackBlock id=\"3d63fb09e0c04488\" body=\"You can opt-in to use Base UI by replacing fumadocs-ui with the @fumadocs/base-ui package:\">\n  You can opt-in to use Base UI by replacing `fumadocs-ui` with the `@fumadocs/base-ui` package:\n</FeedbackBlock>\n\n```json title=\"package.json\"\n{\n  \"dependency\": {\n    \"fumadocs-ui\": \"npm:@fumadocs/base-ui@latest\"\n  }\n}\n```\n\n<FeedbackBlock id=\"78eaeb87e0385d2c\" body=\"For Fumadocs CLI, also configure it in your cli.json config:\">\n  For Fumadocs CLI, also configure it in your `cli.json` config:\n</FeedbackBlock>\n\n```json title=\"cli.json\"\n{\n  \"uiLibrary\": \"base-ui\"\n}\n```\n";
